package com.example.application_service.configuration;import com.example.application_service.security.IdentityArgumentResolver;import org.springframework.context.annotation.Configuration;import org.springframework.web.method.support.HandlerMethodArgumentResolver;import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;import java.util.List;@Configuration public class WebConfiguration implements WebMvcConfigurer{private final IdentityArgumentResolver identity;public WebConfiguration(IdentityArgumentResolver i){identity=i;}public void addArgumentResolvers(List<HandlerMethodArgumentResolver> r){r.add(identity);}}
